contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two inputs: an amount to deposit and a flag whether to attempt withdraw.
    // The test deposits 'amount' into c from this contract, then calls withdrawAll,
    // and asserts the invariant relating c's public observed state, balances, and success.
    function run(uint amount, bool doWithdraw) public payable {
        require(address(this).balance >= amount, "insufficient balance for deposit");

        // Read initial observable values
        uint beforeContractBal = address(c).balance;

        // Make a deposit from this contract to c
        c.deposit{value: amount}();

        // After deposit, the contract balance must have increased by amount
        uint afterDepositContractBal = address(c).balance;
        // decide to call withdrawAll or not
        bool reverted;
        // Capture balance of this test contract before withdraw attempt
        uint beforeThisBal = address(this).balance;
        // Read credited amount via public getter: credit is not public in C, so cannot read it directly.
        // Instead, infer expected transfer: since withdrawAll sends msg.sender.call{value: oCredit} and sets credit to 0,
        // the only observable effect is change in address(c).balance and address(this).balance and success/revert.

        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = false;
        }

        uint finalContractBal = address(c).balance;
        uint finalThisBal = address(this).balance;

        // Assert general rule:
        // If we did not call withdrawAll (doWithdraw == false) then balances change only by the deposit: finalContractBal - beforeContractBal == amount
        // If we called withdrawAll and it reverted, contract balance remains as after deposit (no changes from a reverted withdraw)
        // If we called withdrawAll and it succeeded, then the contract's balance decreased by exactly the increase that this test contract received:
        // (afterDepositContractBal - finalContractBal) == (finalThisBal - beforeThisBal)
        assert(
            (!doWithdraw && finalContractBal - beforeContractBal == amount)
            || (doWithdraw && reverted && finalContractBal - beforeContractBal == amount)
            || (doWithdraw && !reverted && (afterDepositContractBal - finalContractBal) == (finalThisBal - beforeThisBal))
        );
    }

    // Allow this contract to receive Ether when c calls back during withdrawAll
    receive() external payable {}
}

