contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // observe C's balance before any action
        uint beforeCbal = address(c).balance;

        // deposit into C: top-level state-changing call
        c.deposit{value: depositAmount}();

        // read credited amount for this contract after deposit via auto getter
        uint creditedAfterDeposit = c.credit(address(this));

        // record C balance after deposit
        uint afterDepositCbal = address(c).balance;

        // prepare for withdrawAll call and capture whether it reverted
        bool reverted;
        if (doWithdraw) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true; // treat as not-called, so assertion will not demand success-case properties
        }

        // read post-withdraw values
        uint finalCbal = address(c).balance;
        uint creditedAfter = c.credit(address(this));

        // General rule:
        // If withdrawAll was called and did not revert, then:
        //  - credited amount before withdraw equals the decrease in C's balance caused by the withdraw,
        //  - and C's recorded credit for this contract is zero after the withdraw.
        assert(
            (!doWithdraw) || reverted || (
                creditedAfterDeposit == (afterDepositCbal - finalCbal)
                && creditedAfter == 0
            )
        );
    }

    // allow receiving Ether from C on successful withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    // depositAmount: amount to deposit into C from this contract
    // doWithdraw: whether to call withdrawAll
    function run(uint depositAmount, bool doWithdraw) public payable {
        // ensure this test contract has enough Ether to perform the deposit
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record C balance before any action
        uint beforeCbal = address(c).balance;

        // deposit into C: top-level state-changing call
        c.deposit{value: depositAmount}();

        // C balance after deposit
        uint afterDepositCbal = address(c).balance;

        // optionally call withdrawAll and record whether it reverted
        bool reverted;
        uint receivedDuringWithdraw = 0;
        if (doWithdraw) {
            // record this contract balance before withdraw to measure received Ether
            uint beforeThisBal = address(this).balance;
            try c.withdrawAll() {
                reverted = false;
                // measure Ether received as change in this contract's balance
                receivedDuringWithdraw = address(this).balance - beforeThisBal;
            } catch {
                reverted = true;
                receivedDuringWithdraw = 0;
            }
        } else {
            reverted = true; // treat as not-called
        }

        // C balance after withdraw (or after deposit if not called or reverted)
        uint finalCbal = address(c).balance;

        // Attempt a second withdraw to observe that no more Ether is sent if first succeeded
        // We must do it as a separate try to detect revert vs success and measure any extra Ether
        bool secondReverted;
        uint receivedDuringSecond = 0;
        if (doWithdraw && !reverted) {
            uint beforeSecondBal = address(this).balance;
            try c.withdrawAll() {
                secondReverted = false;
                receivedDuringSecond = address(this).balance - beforeSecondBal;
            } catch {
                secondReverted = true;
                receivedDuringSecond = 0;
            }
        } else {
            secondReverted = true;
            receivedDuringSecond = 0;
        }

        // General rule asserted:
        // If withdrawAll was called and did not revert, then
        // 1) finalCbal = afterDepositCbal - receivedDuringWithdraw (C's balance decreased exactly by amount actually received), and
        // 2) the subsequent withdrawAll call sends no additional Ether (receivedDuringSecond == 0).
        assert((!doWithdraw) || reverted || (
            finalCbal + receivedDuringWithdraw == afterDepositCbal
            && receivedDuringSecond == 0
        ));
    }

    // allow receiving Ether from C on successful withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // depositAmount: amount to deposit into C from this contract
    // callWithdraw: whether to call withdrawAll
    function run(uint depositAmount, bool callWithdraw) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // record C balance before deposit
        uint beforeCbal = address(c).balance;

        // Top-level state-changing call: deposit into C
        c.deposit{value: depositAmount}();

        // observe C balance after deposit
        uint afterDepositCbal = address(c).balance;

        // Prepare for first withdraw measurement
        bool firstReverted;
        uint receivedFirst = 0;

        // Call withdrawAll at top-level (must be done even if callWithdraw is false we still perform a top-level call to satisfy shape)
        if (callWithdraw) {
            uint beforeThisBal1 = address(this).balance;
            try c.withdrawAll() {
                firstReverted = false;
                receivedFirst = address(this).balance - beforeThisBal1;
            } catch {
                firstReverted = true;
                receivedFirst = 0;
            }
        } else {
            // Do not call withdrawAll; mark as reverted (treat as not-success)
            firstReverted = true;
            receivedFirst = 0;
        }

        // Observe C balance after the first (attempted) withdraw
        uint afterFirstCbal = address(c).balance;

        // Prepare for second withdraw measurement
        bool secondReverted;
        uint receivedSecond = 0;

        // Always perform a top-level second withdraw attempt to measure any further Ether sent
        uint beforeThisBal2 = address(this).balance;
        try c.withdrawAll() {
            secondReverted = false;
            receivedSecond = address(this).balance - beforeThisBal2;
        } catch {
            secondReverted = true;
            receivedSecond = 0;
        }

        // Final C balance after second attempt
        uint finalCbal = address(c).balance;

        // Assert the general rule:
        // If we called withdrawAll (callWithdraw) and the first call did not revert, then
        // 1) C's balance decreased exactly by the Ether actually received in that first successful call: afterDepositCbal == afterFirstCbal + receivedFirst
        // 2) the subsequent withdrawAll sent no additional Ether: receivedSecond == 0
        assert(
            (!callWithdraw) || firstReverted || (
                afterDepositCbal == afterFirstCbal + receivedFirst
                && receivedSecond == 0
            )
        );
    }

    // allow receiving Ether from C on successful withdraw
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: params determine deposit amount and whether to attempt withdrawal
    function run(uint depositAmount, bool doWithdraw) public payable {
        // ensure this contract has enough balance to forward depositAmount
        require(address(this).balance >= depositAmount);

        // read initial observable values
        uint beforeContractBal = address(c).balance;

        // make a deposit to c from this test contract
        c.deposit{value: depositAmount}();

        // read contract balance and the credit for this contract (via autogenerated getter)
        uint afterDepositContractBal = address(c).balance;
        uint creditAfterDeposit = c.credit(address(this));

        // sanity: deposit should increase contract balance by depositAmount and credit reflect increase
        // We won't assert that here; instead we use these values in the final invariant.

        bool withdrewReverted = false;
        uint balBeforeWithdraw = address(this).balance;
        if (doWithdraw) {
            // attempt withdrawAll and catch revert
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }
        uint balAfterWithdraw = address(this).balance;
        uint afterAllContractBal = address(c).balance;
        uint creditAfterAll = c.credit(address(this));

        // General rule:
        // If we attempted withdraw (doWithdraw == true) and it did NOT revert, then this contract's balance
        // must have increased by exactly the creditAfterDeposit, the contract c's balance must have decreased by the same amount,
        // and the recorded credit for this caller must be zero.
        // Otherwise (either we didn't attempt withdraw, or the withdraw reverted), c's balance and recorded credit must remain as after deposit.
        assert(
            (
                doWithdraw && !withdrewReverted
            ) ? (
                // successful withdraw: test contract gained exactly creditAfterDeposit, c lost same, and credit cleared
                balAfterWithdraw == balBeforeWithdraw + creditAfterDeposit
                && afterAllContractBal + creditAfterDeposit == afterDepositContractBal
                && creditAfterAll == 0
            ) : (
                // not withdrawn or reverted: balances and credit unchanged since after deposit
                balAfterWithdraw == balBeforeWithdraw
                && afterAllContractBal == afterDepositContractBal
                && creditAfterAll == creditAfterDeposit
            )
        );
    }

    // accept Ether for withdrawals
    receive() external payable { }
}

contract InvMutTest {
