        require(address(this).balance >= depositAmount);

        // record balances before any interaction
        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;

        // perform deposit into c from this contract
        c.deposit{value: depositAmount}();

        // balances after deposit
        uint afterDepositThis = address(this).balance;
        uint afterDepositC = address(c).balance;

        // basic sanity: deposit transfers Ether from this to c
        // (we don't assert it here; use in final invariant)

        bool withdrewReverted = false;
        uint balBeforeWithdraw = address(this).balance;

        if (doWithdraw) {
            try c.withdrawAll() {
                withdrewReverted = false;
            } catch {
                withdrewReverted = true;
            }
        }

        uint balAfterWithdraw = address(this).balance;
        uint afterAllC = address(c).balance;

        // General rule: either withdraw succeeded and this contract gained exactly the depositAmount
