                balAfterWithdraw + depositAmount == balBeforeWithdraw
                && afterAllC + depositAmount == afterDepositC
            ) : (
                // not withdrawn or reverted: balances unchanged since after deposit
                balAfterWithdraw == balBeforeWithdraw
                && afterAllC == afterDepositC
            )
        );
    }

    // accept Ether for withdrawals
    receive() external payable { }
