contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: decide an amount to deposit first and a boolean whether to withdraw
    function run(uint depositAmount, bool doWithdraw) public payable {
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Make a deposit from this test contract to C if depositAmount>0
        if (depositAmount > 0) {
            // deposit increases credit[msg.sender] for this test contract
            c.deposit{value: depositAmount}();
        }

        // Now artificially try to withdraw either from the same caller (this contract) or from a different caller
        // We need to observe behavior when caller has zero credit: so call withdrawAll via a different address.
        // However we cannot change msg.sender; but we can ensure zero-credit case by calling from an address that hasn't deposited.
        // To achieve that within constraints, perform withdrawAll via a delegate call through c from this contract only when we first reset credit by withdrawing everything.

        // Ensure there exists an address with zero credit: deploy-time fresh address isn't available, but the simplest is
        // to use the InvMutTest itself but only after ensuring its credit is zero. If depositAmount==0 then this contract has zero credit.
        // So we will test the property only when depositAmount == 0: require that precondition holds.
        require(depositAmount == 0);

        // Recompute balances before trying the withdraw (should equal before values)
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        bool reverted;
        // Call withdrawAll as this contract which currently has zero credit
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After calling withdrawAll with zero credit, C's balance must be unchanged and this contract must not have gained Ether
        assert(address(c).balance == midC && address(this).balance == midThis);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that withdrawAll is a no-op for callers with zero credit
    // Parameters: an initial deposit amount (to possibly give this contract credit) and a flag forcing zero-credit path
    function run(uint initialDeposit, bool forceZero) public payable {
        require(address(this).balance >= initialDeposit);

        // If initialDeposit > 0 we will deposit to C to create credit for this contract.
        // To test the zero-credit path we enforce that either initialDeposit == 0 or forceZero == true.
        // If initialDeposit > 0 and forceZero==true we will first deposit then withdraw to reset credit to zero.

        // Record balances before any interactions
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Optionally deposit to create credit for this contract
        if (initialDeposit > 0) {
            c.deposit{value: initialDeposit}();
        }

        // If we want to force zero-credit but we deposited, withdrawAll to reset credit to zero.
        if (forceZero && initialDeposit > 0) {
            // attempt to withdraw whatever credit exists; ignore revert (should not revert under normal behavior)
            bool ok;
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
            // ok may be true or false depending on callback behavior of recipient; but after this point we will assume credit is zero only when ok==true.
            // To ensure we only assert the no-op property when caller indeed has zero credit, require ok==true when we had deposited and then withdrew.
            require(initialDeposit == 0 || ok == true);
        }

        // Now ensure the caller has zero credit by requiring either we never deposited or we deposited then successfully withdrew above.
        require(initialDeposit == 0 || forceZero == true);

        // Record mid balances just before calling withdrawAll to compare after
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        // Call withdrawAll as this contract (which must have zero credit per the preconditions)
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if caller has zero credit, withdrawAll does not revert and does not change balances.
        // We expressed caller has zero credit via the preconditions above. So assert no revert and balances unchanged.
        assert(reverted == false && address(c).balance == midC && address(this).balance == midThis);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    //  - depositAmount: amount (in wei) this test contract will deposit to C to create positive credit.
    // The function is payable so the caller of run can fund this contract beforehand; require checks balance.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // We need depositAmount > 0 to test the positive-credit behavior
        require(depositAmount > 0);

        // Record balances before any interaction
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // Deposit to create positive credit for this contract
        c.deposit{value: depositAmount}();

        // Record balances immediately after deposit and before withdrawAll
        uint midC = address(c).balance;
        uint midThis = address(this).balance;

        // Call withdrawAll and observe whether it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After calling withdrawAll, either it reverted and balances are unchanged from mid values,
        // or it succeeded and C's balance decreased by exactly depositAmount and this contract's balance increased by exactly depositAmount.
        assert(
            (reverted && address(c).balance == midC && address(this).balance == midThis)
            || (!reverted && address(c).balance + depositAmount == midC && address(this).balance == midThis + depositAmount)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(uint depositAmount) public payable {
        // allow any deposit amount; must ensure this contract has enough balance to send
        require(address(this).balance >= depositAmount);

        // record observables before any actions
        uint beforeBalance = address(c).balance;

        // initial credit as observed through the public getter credit(address)
        uint beforeCredit = c.credit(address(this));

        // perform a deposit to set up state (may be zero)
        c.deposit{value: depositAmount}();

        // record after-deposit values
        uint afterDepositBalance = address(c).balance;
        uint afterDepositCredit = c.credit(address(this));

        // call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record final observables
        uint finalBalance = address(c).balance;
        uint finalCredit = c.credit(address(this));

        // General invariant to assert:
        // 1) C's balance never increases as a result of withdrawAll: finalBalance <= afterDepositBalance
        // 2) The caller's recorded credit never increases as a result of withdrawAll: finalCredit <= afterDepositCredit
        // 3) If withdrawAll succeeded (did not revert), then the caller's credit must be zero after the call
        // These together express that withdrawAll only can reduce balances/credits and, on success, clears the caller's credit.
        assert(
            finalBalance <= afterDepositBalance
            && finalCredit <= afterDepositCredit
            && (reverted || finalCredit == 0)
        );
    }

    // allow receiving Ether when c sends funds back
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    // depositAmount is the amount this test will send to c via deposit()
    function run(uint depositAmount) public payable {
        // ensure this contract has funds to perform the deposit
        require(address(this).balance >= depositAmount);

        // record balances before any action
        uint beforeCTestBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // perform a deposit to set up state (may be zero)
        c.deposit{value: depositAmount}();

        // record balances after deposit
        uint afterDepositCTestBalance = address(c).balance;
        uint afterDepositThisBalance = address(this).balance;

        // call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // record final balances
        uint finalCTestBalance = address(c).balance;
        uint finalThisBalance = address(this).balance;

        // General invariant asserted:
        // 1) C's balance never increased as a result of withdrawAll: finalCTestBalance <= afterDepositCTestBalance
        // 2) The test contract's balance never decreased as a result of withdrawAll: finalThisBalance >= afterDepositThisBalance
        // 3) If withdrawAll succeeded, then C's balance decreased by at most the amount that C gained from our deposit (i.e., at most depositAmount):
        //    afterDepositCTestBalance - finalCTestBalance <= depositAmount
        // These together capture that withdrawAll cannot increase C's balance, cannot take Ether from this test without sending it back, and when successful it can remove at most what our deposit added.
        assert(
            finalCTestBalance <= afterDepositCTestBalance
            && finalThisBalance >= afterDepositThisBalance
            && (reverted || (afterDepositCTestBalance - finalCTestBalance <= depositAmount))
        );
    }

    // allow receiving Ether when c sends funds back
    receive() external payable {}
}
